public class Main {
    static int modify(int[] arr, int idx) {
        arr[idx] = arr[idx] * 2;
        return arr[idx];
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5};
        int sum = 0;

        for (int i = 0; i < numbers.length; i++) {
            if (i % 2 == 0) {
                sum += modify(numbers, i);
            } else {
                sum += numbers[i];
            }
        }

        for (int n : numbers) {
            System.out.print(n + " ");
        }
        System.out.println();
        System.out.println("sum = " + sum);
    }
}

#include <stdio.h>

int main(void) {
    int arr[5] = {10, 20, 30, 40, 50};
    int *p = arr;
    int total = 0;

    for (int i = 0; i < 5; i++) {
        if (i < 2) {
            *(p + i) = *(p + i) + 5;
        } else {
            *(p + i) = *(p + i) - 5;
        }
        total = total + *(p + i);
    }

    for (int i = 0; i < 5; i++) {
        printf("%d ", arr[i]);
    }
    printf("\ntotal = %d\n", total);

    return 0;
}

